#!/usr/bin/env python3
"""Lift an upstream checkpoint crown (a stop-court receipt directory) into er: facts.

usage: import-crown-lift.py <receipts_dir> <crown_sha> <paired_sha>
                            [--required-gates N] [--paired-field ggen_igniter_sha]

The directory holds one STOP receipt (identity.subject "<checkpoint>/STOP") and the
gate receipts of that checkpoint (a `gate` object with gate.checkpoint). <crown_sha> and
<paired_sha> are the exact commits the importing release binds (consumer-owned); gate 090
compares them with what the receipts say. Output is Turtle on stdout, a pure function of
the receipt bytes and the arguments (no paths, no clock), so a committed lift is re-checked
with `cmp`. A null counter is omitted (gate 090 refuses absence). The gate count is the
court's own "N/M gates ALIVE" denominator unless --required-gates pins it.
"""
import argparse, hashlib, json, re
from pathlib import Path
from urllib.parse import quote

ap = argparse.ArgumentParser()
ap.add_argument("receipts_dir"); ap.add_argument("crown_sha"); ap.add_argument("paired_sha")
ap.add_argument("--required-gates", type=int); ap.add_argument("--paired-field", default="ggen_igniter_sha")
a = ap.parse_args()
docs = [(p.read_bytes(), json.loads(p.read_bytes())) for p in sorted(Path(a.receipts_dir).glob("*.json"))]
stops = [(raw, r) for raw, r in docs if str((r.get("identity") or {}).get("subject", "")).endswith("/STOP")]
if len(stops) != 1:
    raise SystemExit(f"import-crown-lift: expected exactly one STOP receipt in {a.receipts_dir}, found {len(stops)}")
raw, stop = stops[0]
cp = stop["identity"]["subject"].rsplit("/", 1)[0]
lit = lambda v: json.dumps(str(v), ensure_ascii=False)
iri = lambda *parts: "<urn:er:imported-crown:" + ":".join(quote(str(x), safe="-._~") for x in parts) + ">"
state = lambda v: f"er:{v}" if re.fullmatch(r"[A-Z_]+", str(v)) else lit(v)
repo = str(stop["identity"].get("repo", ""))
m = re.search(r"(\d+)/(\d+) gates ALIVE", str(stop["standing"].get("derived_from", "")))
required = a.required_gates if a.required_gates is not None else (int(m.group(2)) if m else None)
crown, cc, pc = iri(cp, "crown"), iri(cp, "component", "crown"), iri(cp, "component", "paired")
out = ["@prefix er: <http://seanchatmangpt.github.io/packs/chatman-ecosystem-release#> .", "",
       "# GENERATED by chatman-ecosystem-release-pack bin/import-crown-lift.py. Do not hand-edit.",
       f"{crown} a er:ImportedCrown ;", f"    er:crownCheckpoint {lit(cp)} ;",
       f"    er:crownComponent {cc} ;", f"    er:pairedComponent {pc} ;",
       f"    er:crownSubjectSha {lit(stop['identity'].get('subject_sha'))} ;",
       f"    er:stopStanding {state(stop['standing'].get('value'))} ;",
       f'    er:stopReceiptSha256 "sha256:{hashlib.sha256(raw).hexdigest()}" .']
if required is not None:
    out.append(f"{crown} er:requiredGateCount {int(required)} .")
for key, prop in (("LLM_INVOCATIONS_ON_KNOWN_REFERENCE_PATH", "llmInvocationsOnKnownReferencePath"),
                  ("UNRECEIPTED_ACTUATION", "unreceiptedActuation")):
    v = ((stop.get("release_counters") or {}).get(key) or {}).get("value")
    if v is not None:
        out.append(f"{crown} er:{prop} {v if type(v) is int else lit(v)} .")
out.append(f"{cc} a er:ImportedComponent ; er:commitSha {lit(a.crown_sha)} .")
out.append(f"{pc} a er:ImportedComponent ; er:commitSha {lit(a.paired_sha)} .")
if re.fullmatch(r"[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+", repo):
    out.append(f"{cc} er:repository {lit(repo)} .")
    out.append(f"{pc} er:repository {lit(repo.split('/')[0] + '/' + a.paired_field.removesuffix('_sha'))} .")
for graw, g in docs:
    gate = g.get("gate")
    if not isinstance(gate, dict) or gate.get("checkpoint") != cp:
        continue
    gi = iri(cp, "gate", gate.get("gate"), hashlib.sha256(graw).hexdigest()[:12])
    out += [f"{crown} er:hasGateReceipt {gi} .", f"{gi} a er:ImportedGateReceipt ;",
            f"    er:gateId {lit(gate.get('gate'))} ;", f"    er:gateStanding {state(g['standing'].get('value'))} ;",
            f"    er:gateSubjectSha {lit(g['identity'].get('subject_sha'))} ;"]
    if gate.get(a.paired_field) is not None:
        out.append(f"    er:pairedSubjectSha {lit(gate.get(a.paired_field))} ;")
    out.append(f'    er:receiptSha256 "sha256:{hashlib.sha256(graw).hexdigest()}" .')
print("\n".join(out))
